python3 -c "
import json
with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)

# Search for exchange rate related content
def search_exchange(obj, path='', depth=0):
    if depth > 5:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            lower_k = k.lower() if isinstance(k, str) else ''
            if 'exchange' in lower_k or 'rate' in lower_k or 'pound' in lower_k or 'sterling' in lower_k or 'foreign' in lower_k:
                print(f'{path}.{k}')
            search_exchange(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:10]):
            search_exchange(item, f'{path}[{i}]', depth+1)

search_exchange(data)
"
